using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class FinishCaveHillside{
 public static string Main(){var b=Object.FindObjectsByType<WoodlandRoute>().Single(x=>x.title=="Echo Cave");var hill=GameObject.Find("Ground_Echo wooded hillside");var hm=hill.GetComponent<MeshFilter>().sharedMesh;var tri=hm.triangles;if(hm.normals.Average(n=>n.y)<0){for(int i=0;i<tri.Length;i+=3){int t=tri[i+1];tri[i+1]=tri[i+2];tri[i+2]=t;}hm.triangles=tri;hm.RecalculateNormals();EditorUtility.SetDirty(hm);hill.GetComponent<MeshCollider>().sharedMesh=null;hill.GetComponent<MeshCollider>().sharedMesh=hm;}
 foreach(int row in new[]{0,140}){var g=GameObject.Find("Echo eroded hillside face "+row);var mesh=g.GetComponent<MeshFilter>().sharedMesh;var old=mesh.vertices;var v=new List<Vector3>();var t=new List<int>();var c=new List<Color>();float s=row==0?60:479;var p=b.At(s,out var f);f=Vector3.ProjectOnPlane(f,Vector3.up).normalized;var side=Vector3.Cross(Vector3.up,f).normalized;for(int j=0;j<old.Length/2;j++){var low=old[j*2];var top=old[j*2+1];float x=Vector3.Dot(low-p,side);float spread=Mathf.SmoothStep(0,1,Mathf.InverseLerp(5.7f,15,Math.Abs(x)))*(12+3*Mathf.Sin(x*.2f));for(int k=0;k<5;k++){float u=k/4f;var q=Vector3.Lerp(low,top,u);q+=f*(row==0?-1:1)*spread*(1-u)*(1-u);if(k>0&&k<4)q.y+=.45f*Mathf.Sin(x*.65f+k)*Mathf.Sin(u*Mathf.PI);v.Add(q);c.Add(Color.Lerp(new Color(.40f,.38f,.28f),new Color(.38f,.46f,.30f),u));if(j>0&&k>0){int a=(j-1)*5+k-1;t.AddRange(row==0?new[]{a,a+5,a+1,a+1,a+5,a+6}:new[]{a,a+1,a+5,a+1,a+6,a+5});}}}mesh.Clear();mesh.SetVertices(v);mesh.SetTriangles(t,0);mesh.SetColors(c);mesh.uv=v.Select(q=>new Vector2(q.x,q.z)*.08f).ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);g.GetComponent<MeshCollider>().sharedMesh=null;g.GetComponent<MeshCollider>().sharedMesh=mesh;g.GetComponent<Renderer>().sharedMaterial=hill.GetComponent<Renderer>().sharedMaterial;}
 EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();return "Outward earth normals and irregular sloping portal banks";}
}
